import React, { useState, useEffect } from 'react';
import { X, Plus, Trash2, Users, DollarSign, Sparkles, Lightbulb } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import toast from 'react-hot-toast';
import API from '../utils/api';
import '../styles/modal.css';

export default function ExpenseForm({ groupId, groups, onClose, onSuccess, editingExpense }) {
  const [selectedGroup, setSelectedGroup] = useState(groupId || (groups[0]?._id));
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [paidBy, setPaidBy] = useState('');
  const [splitType, setSplitType] = useState('equal'); // 'equal' or 'custom'
  const [splits, setSplits] = useState([]);
  const [participants, setParticipants] = useState([]); // For equal split
  const [loading, setLoading] = useState(false);

  const group = groups.find(g => g._id === selectedGroup);

  // Initialize form data for editing
  useEffect(() => {
    if (editingExpense) {
      setDescription(editingExpense.description || '');
      setAmount(editingExpense.amount?.toString() || '');
      setPaidBy(editingExpense.paidBy?._id || '');
      setSplitType(editingExpense.splitType || 'equal');
      if (editingExpense.splitType === 'equal') {
        setParticipants(editingExpense.participants?.map(p => p._id) || []);
      } else {
        setSplits(editingExpense.splits || []);
      }
    }
  }, [editingExpense]);

  // Initialize participants for equal split
  useEffect(() => {
    if (splitType === 'equal' && group && participants.length === 0) {
      setParticipants(group.members.map(m => m.user._id));
    }
  }, [splitType, group, participants.length]);

  const handleAddSplit = () => {
    setSplits([...splits, { user: '', amount: '' }]);
  };

  const handleRemoveSplit = (index) => {
    setSplits(splits.filter((_, i) => i !== index));
  };

  const handleUpdateSplit = (index, field, value) => {
    const newSplits = [...splits];
    newSplits[index][field] = value;
    setSplits(newSplits);
  };

  const handleParticipantToggle = (userId) => {
    setParticipants(prev => 
      prev.includes(userId) 
        ? prev.filter(id => id !== userId)
        : [...prev, userId]
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!description || !amount || !paidBy) {
      toast.error('Please fill in all required fields');
      return;
    }

    // Validate split data
    if (splitType === 'equal' && participants.length === 0) {
      toast.error('Please select at least one participant');
      return;
    }
    if (splitType === 'custom' && splits.length === 0) {
      toast.error('Please add at least one split');
      return;
    }

    setLoading(true);
    try {
      const expenseData = {
        description,
        amount: parseFloat(amount),
        paidBy,
        splitType,
      };

      if (splitType === 'equal') {
        expenseData.participants = participants;
      } else {
        expenseData.splits = splits.map(s => ({
          user: s.user,
          amount: parseFloat(s.amount)
        }));
      }

      const apiUrl = editingExpense 
        ? `/groups/${selectedGroup}/expenses/${editingExpense._id}`
        : `/groups/${selectedGroup}/expenses`;
      
      if (editingExpense) {
        await API.put(apiUrl, expenseData);
      } else {
        await API.post(apiUrl, expenseData);
      }
      toast.success(editingExpense ? 'Expense updated successfully!' : 'Expense added successfully!');
      onSuccess?.();
    } catch (error) {
      toast.error(error.response?.data?.message || `Failed to ${editingExpense ? 'update' : 'add'} expense`);
    } finally {
      setLoading(false);
    }
  };

  const modalVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1 }
  };

  const contentVariants = {
    hidden: { y: 50, opacity: 0 },
    visible: { y: 0, opacity: 1 }
  };

  return (
    <AnimatePresence>
      <motion.div
        className="modal-overlay"
        variants={modalVariants}
        initial="hidden"
        animate="visible"
        exit="hidden"
      >
        <motion.div
          className="modal-content"
          variants={contentVariants}
          initial="hidden"
          animate="visible"
          exit="hidden"
        >
          <div className="modal-header">
            <h2>{editingExpense ? 'Edit Expense' : 'Add Expense'}</h2>
            <button className="close-btn" onClick={onClose}>
              <X size={24} />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="expense-form">
            {!groupId && (
              <div className="form-group">
                <label>Group</label>
                <select value={selectedGroup} onChange={(e) => setSelectedGroup(e.target.value)}>
                  {groups.map(g => (
                    <option key={g._id} value={g._id}>{g.name}</option>
                  ))}
                </select>
              </div>
            )}

            <div className="form-row">
              <div className="form-group">
                <label>Description</label>
                <input
                  type="text"
                  placeholder="Lunch, Gas, etc."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </div>
              <div className="form-group">
                <label>Amount</label>
                <input
                  type="number"
                  placeholder="0.00"
                  step="0.01"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                />
              </div>
            </div>

            <div className="form-group">
              <label>Paid By</label>
              <select value={paidBy} onChange={(e) => setPaidBy(e.target.value)}>
                <option value="">Select member</option>
                {group?.members?.map(m => (
                  <option key={m.user._id} value={m.user._id}>{m.user.name}</option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label>Split Type</label>
              <div className="split-type-selector">
                <label className="radio-option">
                  <input
                    type="radio"
                    name="splitType"
                    value="equal"
                    checked={splitType === 'equal'}
                    onChange={(e) => setSplitType(e.target.value)}
                  />
                  <span className="radio-label">
                    <Users size={16} />
                    Equal Split
                  </span>
                </label>
                <label className="radio-option">
                  <input
                    type="radio"
                    name="splitType"
                    value="custom"
                    checked={splitType === 'custom'}
                    onChange={(e) => setSplitType(e.target.value)}
                  />
                  <span className="radio-label">
                    <DollarSign size={16} />
                    Custom Split
                  </span>
                </label>
              </div>
            </div>

            {splitType === 'equal' ? (
              <div className="form-group">
                <label>Participants</label>
                <p className="form-hint">Select who will share this expense equally</p>
                <div className="participants-grid">
                  {group?.members?.map(m => (
                    <label key={m.user._id} className="participant-checkbox">
                      <input
                        type="checkbox"
                        checked={participants.includes(m.user._id)}
                        onChange={() => handleParticipantToggle(m.user._id)}
                      />
                      <span className="checkbox-label">
                        {m.user.name}
                      </span>
                    </label>
                  ))}
                </div>
                {participants.length > 0 && (
                  <div className="split-summary">
                    <p>Each person pays: <strong>${(parseFloat(amount || 0) / participants.length).toFixed(2)}</strong></p>
                  </div>
                )}
              </div>
            ) : (
              <div className="form-group">
                <label>Custom Splits</label>
                <p className="form-hint">Specify how much each person should pay</p>
                <div className="splits-list">
                  {splits.map((split, i) => (
                    <div key={i} className="split-item">
                      <select
                        value={split.user}
                        onChange={(e) => handleUpdateSplit(i, 'user', e.target.value)}
                      >
                        <option value="">Select member</option>
                        {group?.members?.map(m => (
                          <option key={m.user._id} value={m.user._id}>{m.user.name}</option>
                        ))}
                      </select>
                      <input
                        type="number"
                        placeholder="Amount"
                        step="0.01"
                        value={split.amount}
                        onChange={(e) => handleUpdateSplit(i, 'amount', e.target.value)}
                      />
                      <button
                        type="button"
                        className="remove-btn"
                        onClick={() => handleRemoveSplit(i)}
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  ))}
                </div>
                <button type="button" className="btn-secondary" onClick={handleAddSplit}>
                  <Plus size={18} />
                  Add Split
                </button>
                {splits.length > 0 && (
                  <div className="split-summary">
                    <p>Total split: <strong>${splits.reduce((sum, s) => sum + parseFloat(s.amount || 0), 0).toFixed(2)}</strong></p>
                    {Math.abs(splits.reduce((sum, s) => sum + parseFloat(s.amount || 0), 0) - parseFloat(amount || 0)) > 0.01 && (
                      <p className="warning">Split amounts don't match the total expense amount!</p>
                    )}
                  </div>
                )}
              </div>
            )}

            <div className="form-actions">
              <button type="button" className="btn-secondary" onClick={onClose}>
                Cancel
              </button>
              <button type="submit" className="btn-primary" disabled={loading}>
                {loading ? (editingExpense ? 'Updating...' : 'Adding...') : (editingExpense ? 'Update Expense' : 'Add Expense')}
              </button>
            </div>
          </form>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
